// MessageService: Messages. An ID is local and stays the same while the
// message exists, including across moves the server reports with COPYUID.
type MessageService interface {
	// Get implements message.get. One message's headers and structure.
	Get(ctx context.Context, p *MessageGetParams) (*Message, error)
	// Body implements message.body. A message's text, fetching the message from
	// the server first if it is not stored locally.
	Body(ctx context.Context, p *MessageBodyParams) (*Body, error)
	// Summaries implements message.summaries. Summaries of messages in the order
	// given; IDs that no longer exist are skipped.
	Summaries(ctx context.Context, p *MessageSummariesParams) ([]MessageSummary, error)
	// Render implements message.render. A message prepared for the reader,
	// fetching it first if it is not stored locally. Remote images are loaded
	// through maild only when remote is true; tracking images never are.
	Render(ctx context.Context, p *MessageRenderParams) (*Rendering, error)
	// Part implements message.part. Decode one part (an attachment or inline
	// image) into the parts cache.
	Part(ctx context.Context, p *MessagePartParams) (*PartFile, error)
	// SetFlags implements message.setFlags. Change flags locally at once and on
	// the server when it can be reached.
	SetFlags(ctx context.Context, p *MessageSetFlagsParams) error
	// Move implements message.move. Move messages to another mailbox of the same
	// account.
	Move(ctx context.Context, p *MessageMoveParams) error
	// Copy implements message.copy. Copy messages to another mailbox of their
	// account. On Gmail the copy is the destination label, added at once; only
	// labels can be copied into. Elsewhere the server makes a new message, which
	// appears in the destination once the server has it (on the next replay while
	// online). Messages already in the destination are skipped.
	Copy(ctx context.Context, p *MessageCopyParams) error
	// Delete implements message.delete. Move messages to the account's Trash;
	// messages already in Trash are deleted from the server.
	Delete(ctx context.Context, p *MessageDeleteParams) error
	// Remind implements message.remind. Remind Me: at a time, bring messages back
	// to the top of their account's inbox and notify (ADR-0025). Without at,
	// clear their reminders. Conflict for a read-only account's messages.
	Remind(ctx context.Context, p *MessageRemindParams) error
}

