// DecodeEvent decodes the data of the named event.
func DecodeEvent(name string, data jsontext.Value) (Event, error) {
	switch name {
	case "account.changed":
		var e AccountChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "calendar.changed":
		var e CalendarChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "calendar.reminders":
		var e CalendarReminders
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "draft.changed":
		var e DraftChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "mailbox.changed":
		var e MailboxChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "message.changed":
		var e MessageChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "message.removed":
		var e MessageRemoved
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "outbox.changed":
		var e OutboxChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "people.changed":
		var e PeopleChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "rule.changed":
		var e RuleChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "settings.changed":
		var e SettingsChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "smart.changed":
		var e SmartChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "sync.progress":
		var e SyncProgress
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "tasks.changed":
		var e TasksChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "view.delta":
		var e ViewDelta
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	case "vip.changed":
		var e VipChanged
		if err := json.Unmarshal(data, &e); err != nil {
			return nil, fmt.Errorf("decode event %s: %w", name, err)
		}
		return e, nil
	}
	return nil, fmt.Errorf("unknown event %q", name)
}
